<script setup>const {data:me}=await useFetch('/api/me');const {data:apps,refresh}=await useFetch('/api/apps');const q=ref('');const filtered=computed(()=>apps.value?.filter(a=>(a.name+' '+(a.description||'')+' '+(a.category||'')).toLowerCase().includes(q.value.toLowerCase()))||[]);const fav=computed(()=>filtered.value.filter(a=>a.favorite));const recent=computed(()=>filtered.value.filter(a=>a.visitedAt).sort((a,b)=>String(b.visitedAt).localeCompare(String(a.visitedAt))).slice(0,6));const grouped=computed(()=>Object.groupBy(filtered.value,a=>a.category||'Lainnya'));async function open(a){const r=await $fetch(`/api/apps/${a.id}/open`,{method:'POST'});window.open(r.url,'_blank','noopener,noreferrer');refresh()}async function favorite(a){await $fetch(`/api/apps/${a.id}/favorite`,{method:'POST'});refresh()}async function logout(){await $fetch('/api/auth/logout',{method:'POST'});navigateTo('/login')}</script><template><header class="top"><div class="brand">AppDesk · {{me.companyName}}</div><nav class="nav"><NuxtLink v-if="me.role!=='USER'" to="/admin">Admin</NuxtLink><a href="#" @click.prevent="logout">Keluar</a></nav></header><main class="wrap"><section class="hero"><h1>Halo, {{me.name}}</h1><p>Temukan aplikasi kerja Anda dari satu tempat.</p><input v-model="q" class="search" placeholder="Cari aplikasi..."></section><section v-if="fav.length" class="section"><h2>Favorit</h2><div class="grid"><AppCard v-for="a in fav" :key="a.id" :app="a" @open="open" @favorite="favorite"/></div></section><section v-if="recent.length" class="section"><h2>Terakhir dibuka</h2><div class="grid"><AppCard v-for="a in recent" :key="a.id" :app="a" @open="open" @favorite="favorite"/></div></section><section v-for="(items,name) in grouped" :key="name" class="section"><h2>{{name}}</h2><div class="grid"><AppCard v-for="a in items" :key="a.id" :app="a" @open="open" @favorite="favorite"/></div></section></main></template>